<template>
  <section ref="detailRoot" class="subchat-detail" :data-chat-id="chatId" @keydown="detailKey">
    <header class="subchat-detail-header"><button type="button" class="ui-icon-button" title="返回子对话列表" aria-label="返回子对话列表" @click="emit('back')"><AppIcon icon="arrow-left"/></button><img :src="subchatGlyphUrl(chatId)" alt=""/><div class="subchat-detail-heading"><h2 :title="chat?.title">{{chat?.title||'子对话'}}</h2><span>{{pendingCount?'需要处理':state.running?'进行中':subchatStatusLabels[chat?.subchatRun?.status||chat?.spawnStatus||'done']}}</span></div><slot name="tools"/></header>
    <ConversationFind ref="find" find-scope="workspace" :target-title="chat?.title||'当前子对话'" :target-key="`subchat:${parentChatId}:${chatId}`" :chat-id="chatId" :active="active" :messages="chat?.messages||[]" :live-text="state.liveText" :root="scroller||null" :display-text="message=>message.content" :locate="locate"/>
    <p v-if="state.loading&&!chat" class="subchat-detail-empty" role="status">正在读取子对话…</p>
    <p v-else-if="state.deleted" class="subchat-detail-empty">这个子对话已被删除。<button type="button" @click="emit('back')">返回列表</button></p>
    <p v-else-if="!valid&&state.chat" class="subchat-detail-empty" role="alert">这个子对话不属于当前父对话。<button type="button" @click="emit('back')">返回列表</button></p>
    <p v-if="state.error||localError" class="subchat-detail-error" role="alert">{{localError||state.error}} <button type="button" @click="reload">重新读取</button></p>
    <div v-if="chat" ref="scroller" class="subchat-detail-scroll" tabindex="-1" @scroll="saveScroll">
      <details v-if="chat.spawnPurpose" class="subchat-purpose"><summary>任务说明</summary><p>{{chat.spawnPurpose}}</p><button type="button" @click="emit('locate-parent',{chatId:parentChatId,toolCallId:chat.parentToolCallId})">定位父聊天中的委派</button></details>
      <p v-if="chat.subchatRun?.status==='interrupted'" class="subchat-interrupted">上次运行因应用退出而中断。任务记录已保留，可以继续交流或重试。</p>
      <template v-for="message in detailMessages" :key="message.id">
      <ConversationProcessToggle v-if="processHeaders.has(message.id)" :group="processHeaders.get(message.id)!" :open="!!expandedProcesses[processHeaders.get(message.id)!.key]" @toggle="toggleProcess(processHeaders.get(message.id)!.key)"/>
      <div v-show="!processMessageHidden(message.id)" :data-msg-id="message.id" class="subchat-message" :class="`subchat-message-${message.role}`">
        <template v-if="message.role==='assistant'||message.role==='user'"><div class="subchat-message-role">{{message.role==='user'?'你':'助手'}}</div><p v-if="message.role==='user'&&taskDeclarationsLabel(message.meta?.taskConstraints?.declarations??message.meta?.document?.declarations)" class="subchat-phase">本条：{{ taskDeclarationsLabel(message.meta?.taskConstraints?.declarations??message.meta?.document?.declarations) }}</p><ConversationReasoning v-if="message.role==='assistant'&&message.meta?.reasoning&&(!processByMessage.get(message.id)||expandedProcesses[processByMessage.get(message.id)!.key])" :text="String(message.meta.reasoning)"/><ChatMarkdown :chat-id="chatId" :artifact-paths="replyFiles.get(message.id)?.map(file=>file.path)" :content="message.content" @open-file="emit('open-file',{chatId,path:$event})" @notify="emit('notify',$event)"><template v-if="message.role==='assistant'&&finalIds.has(message.id)" #footer><ReplyArtifacts v-if="replyFiles.has(message.id)" :reply-id="message.id" :files="replyFiles.get(message.id)!" @open="(path,owner)=>emit('open-file',{chatId:owner,path})" @notify="emit('notify',$event)"/><div class="subchat-reply-footer"><button type="button" class="ui-icon-button" :title="copied===message.id?'已复制':'复制回答'" :aria-label="copied===message.id?'已复制':'复制回答'" @click="copyReply(message)"><AppIcon :icon="copied===message.id?'check':'copy'"/></button></div></template></ChatMarkdown></template>
        <ConversationActivityRow v-else :message="message" :label="message.role==='log'?String(message.meta?.summary||message.content.split('\n')[0]||'运行记录'):undefined" :icon="message.role==='log'?'clipboard-list':undefined" :expanded="expanded.has(message.id)" :reveal="revealed[message.id]" @toggle="toggleExpanded(message.id)"/>
      </div>
      </template>
      <div v-if="state.liveText" class="subchat-message" data-live-answer><div class="subchat-message-role">助手</div><ChatMarkdown :chat-id="chatId" :content="state.liveText" :shimmer="true" @open-file="emit('open-file',{chatId,path:$event})" @notify="emit('notify',$event)"/></div>
      <ConversationReasoning v-if="state.reasoning" :key="chatId" :text="state.reasoning" label="思考中" />
      <p v-if="state.running" class="subchat-phase" role="status">{{state.phaseDetail||'正在处理任务…'}}</p>
      <InChatAskCard v-for="req in session.asks.value" :key="req.id" :data-request-id="req.id" :req="req" :busy="session.responses.has(req.id)" :submission-error="session.decisionStates[req.id]?.error" :expired="session.decisionStates[req.id]?.expired" @dismiss="session.dismissAsk(req.id)" @option="answer(req.id,$event,'option')" @custom="answer(req.id,$event,'custom')" @deny="answer(req.id,'','deny')"/>
      <InChatPermCard v-for="req in session.permissions.value" :key="req.id" :data-request-id="req.id" :req="req" :capability-label="req.capability" :pending-count="session.permissions.value.length" :busy="session.responses.has(req.id)" :submission-error="session.decisionStates[req.id]?.error" :expired="session.decisionStates[req.id]?.expired" @dismiss="session.dismissPermission(req.id)" @decide="permission(req.id,$event)"/>
      <button v-if="!state.followBottom" type="button" class="subchat-latest" @click="jumpLatest">回到最新消息</button>
    </div>
    <div v-if="chat" class="subchat-composer" @compositionstart.capture="startComposition" @compositionend.capture="finishComposition">
      <MessageQueue :entries="chat.queuedMessages||[]" :paused="!!chat.queuePaused" :busy="busy" :max-chars="maxChars" :chat-id="chatId" :messages="chat.messages" :files="files" @edit="queueEdit" @remove="queueAction('remove',$event)" @insert="queueAction('insert',$event)" @resume="queueAction('resume')" @recover="draft.edited($event)" @notify="emit('notify',$event)" @creator="emit('creator',$event)"/>
      <p v-if="draft.conflict.value" class="subchat-draft-conflict">草稿在另一处有更新，两份内容均已保留。<button type="button" @click="draft.resolveConflict(true)">保留当前编辑</button><button type="button" @click="draft.resolveConflict(false)">使用同步版本</button></p>
      <button v-if="pendingQuestionnaire" type="button" class="subchat-questionnaire-dock" @click="requestOpenQuestionnaire(pendingQuestionnaire.id,chatId)"><AppIcon icon="list-ul"/><span>{{pendingQuestionnaire.title}}</span><span>打开填写</span></button>
      <ComposerEditor v-if="active" ref="editor" :model-value="draft.document.value" :chat-id="chatId" :disabled="busy||draft.unsupported.value" :placeholder="pendingQuestionnaire ? '发送消息可切回聊天讨论问卷…' : '继续交流，或给这个子任务补充说明…'" @update:model-value="draft.edited" @submit="send" @attach="attach" @change-source="changeSource" @open-source="openSource" @refresh-source="changeSource" @notify="emit('notify',$event)"/>
      <div class="subchat-composer-controls"><button ref="attachButton" type="button" class="ui-icon-button" title="附加：点击选择来源，或输入 /" aria-label="附加" :disabled="busy" @click="attach()"><AppIcon icon="paperclip"/></button><label class="subchat-mode"><AppIcon icon="sliders"/><select :value="chat.executionMode||'auto'" aria-label="子对话回答方式" :disabled="busy||configBusy" @change="changeMode"><option value="auto">自动</option><option value="chat">聊天</option><option value="agent">执行</option></select></label><label class="subchat-mode"><AppIcon icon="lock"/><select :value="chat.permissions?.preset||'balanced'" aria-label="子对话会话权限" :disabled="busy||configBusy" @change="changePermission"><option value="conservative">保守</option><option value="balanced">平衡</option><option value="open">放手</option><option v-if="chat.permissions?.preset==='custom'" value="custom">自定义</option></select></label><label class="subchat-model"><select :value="modelKey" aria-label="子对话模型" :disabled="busy||configBusy||!config" @change="changeModel"><option value="" disabled>选择模型</option><optgroup v-for="provider in config?.ai.providers||[]" :key="provider.id" :label="provider.label||provider.id"><option v-for="model in provider.models" :key="model" :value="JSON.stringify([provider.id,model])">{{model}}</option></optgroup></select></label><ComposerSendButton :label="pendingQuestionnaire && mainMode!=='stop' ? '发送并切回聊天' : undefined" :disabled="composing||(mainMode!=='stop'&&!canSend)" :busy="busy" :mode="mainMode" @submit="submitMain"/></div>
      <p v-if="configError" class="subchat-detail-error">{{configError}} <button type="button" @click="loadConfig">重试读取模型</button></p>
    </div>
    <ComposerAttachmentMenu :chat-id="chatId" :files="files" :messages="chat?.messages||[]" @insert="insertSources" v-if="active" ref="attachmentMenu" :context-key="chatId" :selected-declarations="selectedDeclarations" @declaration="selectDeclaration" @select="selectSource" @creator="emit('creator',$event)" @closed="attachmentClosed" @notify="emit('notify',$event)"/>
  </section>
</template>
<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,toRef,watch} from 'vue'
import type {AppConfig} from '@shared/config'
import type {ConversationMatch} from '@shared/conversation-find'
import {modesForPreset} from '@shared/config'
import type {ChatMessage,PermissionDecision,PermissionPreset} from '@shared/types'
import {subchatStatusLabels} from '@shared/subchat-presentation'
import {useSubchatGlyph} from '@/composables/useSubchatGlyph'
import {confirmedModelSelection} from '@shared/model-selection'
import {normalizeTaskDeclarations,taskDeclarationsSupported,taskDeclarationsLabel,type TaskDeclarationId} from '@shared/task-declarations'
import {compileComposerDocument,composerSubmissionKey,type ComposerContextBlock,type ComposerDocument} from '@shared/composer-document'
import {replyArtifactGroups} from '@shared/workspace-resources'
import {finalOutputs} from '@shared/message-presentation'
import type {ComposerEditorHandle,ComposerSelectionBookmark} from '@/editor/composer-editor-registry'
import {loadConversationResources,refreshSubchatIndex,useConversationSession} from '@/composables/useConversationSession'
import {useComposerDraft} from '@/composables/useComposerDraft'
import type {QuestionnaireRecord} from '@shared/questionnaire'
import {requestOpenQuestionnaire} from '@/utils/questionnaire-events'
import {openWindowFind} from '@/composables/useWindowFind'
import AppIcon from './icons/AppIcon.vue'
import ChatMarkdown from './ChatMarkdown.vue'
import ReplyArtifacts from './ReplyArtifacts.vue'
import ConversationActivityRow from './ConversationActivityRow.vue'
import ConversationReasoning from './ConversationReasoning.vue'
import ConversationProcessToggle from './ConversationProcessToggle.vue'
import ComposerSendButton from './ComposerSendButton.vue'
import {conversationOutputBlocks,conversationProcessGroups} from '@shared/conversation-output'
import ConversationFind from './ConversationFind.vue'
import InChatAskCard from './chat/InChatAskCard.vue'
import InChatPermCard from './chat/InChatPermCard.vue'
import ComposerEditor from './ComposerEditor.vue'
import ComposerAttachmentMenu from './ComposerAttachmentMenu.vue'
import MessageQueue from './MessageQueue.vue'
const props=withDefaults(defineProps<{parentChatId:string;chatId:string;active?:boolean}>(),{active:true})
const {glyphUrl:subchatGlyphUrl}=useSubchatGlyph()
const emit=defineEmits<{back:[];'locate-parent':[target:{chatId:string;toolCallId?:string}];'open-file':[target:{chatId:string;path:string}];creator:[kind:'plugin'|'skill'];notify:[message:string]}>()
const session=useConversationSession(toRef(props,'chatId')),state=session.state,valid=computed(()=>state.value.chat?.kind==='sub'&&state.value.chat.parentChatId===props.parentChatId),chat=computed(()=>valid.value?state.value.chat:null),owner=computed<string|null>(()=>props.chatId),draft=useComposerDraft(owner,message=>emit('notify',message))
const detailRoot=ref<HTMLElement>(),scroller=ref<HTMLElement>(),find=ref<InstanceType<typeof ConversationFind>>(),editor=ref<ComposerEditorHandle>(),attachButton=ref<HTMLElement>(),attachmentMenu=ref<InstanceType<typeof ComposerAttachmentMenu>>()
const busy=ref(false),configBusy=ref(false),localError=ref(''),config=ref<AppConfig|null>(null),configError=ref(''),copied=ref(''),expanded=ref(new Set<string>(state.value.expanded)),revealed=ref<Record<string,{from:number;to:number}>>({})
const pendingQuestionnaire=ref<QuestionnaireRecord|null>(null)
let questionnaireGeneration=0
const offQuestionnaires=window.navora?.questionnaires?.onChanged(record=>{if(record.chatId===props.chatId){questionnaireGeneration++;pendingQuestionnaire.value=record.status==='pending'?record:null}})
if(window.navora?.questionnaires){const generation=questionnaireGeneration;void window.navora.questionnaires.list(props.chatId).then((records:QuestionnaireRecord[])=>{if(generation===questionnaireGeneration)pendingQuestionnaire.value=records.find(record=>record.status==='pending')||null}).catch(()=>{})}
let copyTimer:ReturnType<typeof setTimeout>|undefined
const pendingCount=computed(()=>session.asks.value.length+session.permissions.value.length)
const expandedProcesses=ref<Record<string,boolean>>({})
const detailMessages=computed(()=>conversationOutputBlocks(chat.value?.messages||[]).flatMap(block=>block.type==='run'?[]:[block.message]))
const processGroups=computed(()=>conversationProcessGroups(chat.value?.messages||[],state.value.running))
const processHeaders=computed(()=>new Map(processGroups.value.map(group=>[group.firstId,group])))
const processByMessage=computed(()=>new Map(processGroups.value.flatMap(group=>group.messageIds.map(id=>[id,group] as const))))
function processMessageHidden(id:string){const group=processByMessage.value.get(id);return !!group&&group.processIds.has(id)&&!expandedProcesses.value[group.key]}
function toggleProcess(key:string){expandedProcesses.value={...expandedProcesses.value,[key]:!expandedProcesses.value[key]}}
const files=computed(()=>state.value.resources||[]),finalIds=computed(()=>new Set(finalOutputs(chat.value?.messages||[]).map(message=>message.id))),replyFiles=computed(()=>replyArtifactGroups(files.value,chat.value?.messages||[]))
let disposed=false,restored=false,bookmark:ComposerSelectionBookmark|null=null,sourceOwner='',sourceDocumentId=''
const maxChars=computed(()=>config.value?.app.max_composer_chars||16000),modelKey=computed(()=>{try{const model=config.value&&chat.value?confirmedModelSelection(config.value,chat.value):null;return model?JSON.stringify([model.providerId,model.model]):''}catch{return ''}})
const composing=ref(false)
let compositionTimer:ReturnType<typeof setTimeout>|undefined
function startComposition(){clearTimeout(compositionTimer);composing.value=true}
function finishComposition(){clearTimeout(compositionTimer);compositionTimer=setTimeout(()=>{composing.value=false},0)}
const payloadReady=computed(()=>{try{const payload=compileComposerDocument(draft.document.value);return !!(payload.content.trim()||payload.refs.length)&&!payload.contexts.some(item=>item.block.status==='loading'||item.block.mode==='reference'&&['missing','error'].includes(item.block.status||''))}catch{return false}})
const canSend=computed(()=>!!chat.value&&!!modelKey.value&&!busy.value&&!configBusy.value&&!draft.unsupported.value&&!draft.conflict.value&&taskDeclarationsSupported(draft.document.value.declarations)&&payloadReady.value&&compileComposerDocument(draft.document.value).content.length<=maxChars.value)
const mainMode=computed<'send'|'queue'|'stop'>(()=>state.value.running?payloadReady.value?pendingQuestionnaire.value?'send':'queue':'stop':'send')
function submitMain(){if(composing.value||busy.value)return;if(mainMode.value==='stop')void stop();else void send()}
watch(chat,value=>{if(!value)return;if(!restored){draft.load(value);restored=true;void nextTick(()=>{if(scroller.value){scroller.value.scrollTop=state.value.scrollTop;if(state.value.followBottom)scroller.value.scrollTop=scroller.value.scrollHeight;requestAnimationFrame(()=>{if(visible())saveScroll()})}})}else draft.acceptRemote(value)},{immediate:true})
watch(()=>[chat.value?.messages.length,state.value.liveText,session.asks.value.length,session.permissions.value.length],()=>{if(visible()&&state.value.followBottom)void nextTick(jumpLatest)})
watch(()=>state.value.running,(running,was)=>{if(was&&!running)void loadConversationResources(props.chatId,true)})
watch(()=>props.active,active=>{if(!active){attachmentMenu.value?.hide();bookmark=null}else if(state.value.followBottom)void nextTick(jumpLatest)})
function toggleExpanded(id:string){const next=new Set(expanded.value);next.has(id)?next.delete(id):next.add(id);expanded.value=next;state.value.expanded=[...next]}
function visible(){return !disposed&&props.active&&!document.hidden&&!!detailRoot.value?.isConnected&&detailRoot.value.checkVisibility()&&!detailRoot.value.closest('[inert]')}
function saveScroll(){if(!scroller.value)return;state.value.scrollTop=scroller.value.scrollTop;state.value.followBottom=scroller.value.scrollHeight-scroller.value.clientHeight-scroller.value.scrollTop<60;if(visible()&&state.value.followBottom)session.markRead()}
function jumpLatest(){if(!visible()||!scroller.value)return;scroller.value.scrollTop=scroller.value.scrollHeight;saveScroll()}
async function locate(id:string,match?:ConversationMatch){if(match)revealed.value={...revealed.value,[id]:{from:match.from,to:match.to}};const group=processByMessage.value.get(id);if(group&&!expandedProcesses.value[group.key]){expandedProcesses.value={...expandedProcesses.value,[group.key]:true};await nextTick()};const element=scroller.value?.querySelector<HTMLElement>(`[data-msg-id="${CSS.escape(id)}"]`);if(element){if(!expanded.value.has(id)){expanded.value.add(id);state.value.expanded=[...expanded.value]};await nextTick();element.scrollIntoView({block:'center'});saveScroll()}}
async function perform(action:()=>Promise<unknown>){if(!valid.value||busy.value)return;busy.value=true;localError.value='';try{await action()}catch(error){localError.value=error instanceof Error?error.message:'操作失败'}finally{busy.value=false}}
async function loadConfig(){try{config.value=await window.navora!.config.get();configError.value=''}catch{configError.value='暂时无法读取模型设置。'}}
async function reload(){localError.value='';await session.reload()}
async function send(){if(composing.value||!canSend.value)return;await perform(async()=>{const id=props.chatId;await draft.flush(id);if(id!==props.chatId||!chat.value||!config.value)throw Error('当前子对话已切换');const document=JSON.parse(JSON.stringify(draft.document.value)) as ComposerDocument,payload={...compileComposerDocument(document),document,draftRevision:draft.baseRevision(),clientMessageId:composerSubmissionKey(document),modelIdentity:confirmedModelSelection(config.value,chat.value)};const receipt=await window.navora!.agent.submit(id,payload,pendingQuestionnaire.value?'insert':'queue');if(!receipt)throw Error('提交未获确认，内容仍保留在编辑器中');draft.acknowledge(receipt,document);await session.reload();if(!disposed&&id===props.chatId){state.value.followBottom=true;await nextTick();jumpLatest();editor.value?.focus()}})}
async function stop(){await perform(async()=>{await window.navora!.agent.stop(props.chatId);await session.reload()})}
async function retry(){await perform(async()=>{await window.navora!.agent.retry(props.chatId);await session.reload()})}
async function answer(id:string,text:string,source:'option'|'custom'|'deny'){try{await session.respondAsk(id,text,source)}catch(error){emit('notify',error instanceof Error?error.message:'答复失败')}}
async function permission(id:string,decision:PermissionDecision){try{await session.respondPermission(id,decision)}catch(error){emit('notify',error instanceof Error?error.message:'授权答复失败')}}
async function configure(action:()=>Promise<unknown>){if(!valid.value||configBusy.value)return;configBusy.value=true;try{await action();await session.reload()}catch(error){emit('notify',error instanceof Error?error.message:'保存选择失败')}finally{configBusy.value=false}}
function changeMode(event:Event){const mode=(event.target as HTMLSelectElement).value as 'auto'|'chat'|'agent';void configure(()=>window.navora!.chats.setExecutionMode(props.chatId,mode))}
function changePermission(event:Event){const preset=(event.target as HTMLSelectElement).value as PermissionPreset;if(preset==='custom')return;void configure(()=>window.navora!.chats.setPermissions(props.chatId,{preset,modes:modesForPreset(preset)}))}
function changeModel(event:Event){const [provider,model]=JSON.parse((event.target as HTMLSelectElement).value) as string[];void configure(()=>window.navora!.chats.setProvider(props.chatId,provider!,model!,null))}
function queueEdit(id:string,content:string,document:ComposerDocument,baseRevision?:number){void perform(async()=>{await window.navora!.agent.queueEdit(props.chatId,id,content,{document,baseRevision});await session.reload()})}
function queueAction(action:'remove'|'insert'|'resume',id=''){void perform(async()=>{if(action==='remove')await window.navora!.agent.queueRemove(props.chatId,id);else if(action==='insert')await window.navora!.agent.queueInsert(props.chatId,id);else await window.navora!.agent.queueResume(props.chatId);await session.reload()})}
async function showSource(source='file',replacement?:ComposerContextBlock,files?:File[]){const anchor=detailRoot.value?.querySelector<HTMLElement>('.subchat-composer');if(anchor)await attachmentMenu.value?.showSource(anchor,source,replacement,files)}
async function attach(request?:{source?:string;files?:File[]}){if(!valid.value||busy.value)return;bookmark=editor.value?.saveSelection()||null;sourceOwner=props.chatId;sourceDocumentId=draft.document.value.id;if(request?.files?.length){await showSource('file',undefined,request.files);return}if(request?.source){await selectSource(request.source);return}const anchor=detailRoot.value?.querySelector<HTMLElement>('.subchat-composer')||attachButton.value;if(anchor)attachmentMenu.value?.show(anchor)}
const selectedDeclarations=computed(()=>{try{return normalizeTaskDeclarations(draft.document.value.declarations).ids}catch{return []}})
function selectDeclaration(id:TaskDeclarationId){if(sourceOwner!==props.chatId||sourceDocumentId!==draft.document.value.id||!valid.value)return;if(bookmark&&!editor.value?.restoreSelection(bookmark))return;editor.value?.toggleDeclaration(id);bookmark=null}
async function selectSource(source:string){if(sourceOwner!==props.chatId)return;editor.value?.consumeAttachmentTrigger();const owner=props.chatId,documentId=draft.document.value.id;if(!state.value.resources)await loadConversationResources(owner);if(props.active&&sourceOwner===owner&&props.chatId===owner&&draft.document.value.id===documentId)void showSource(source)}
function attachmentClosed(committed:boolean){if(!committed){editor.value?.cancelAttachmentTrigger();pickerClosed()}}
function pickerClosed(){if(sourceOwner===props.chatId&&bookmark)editor.value?.restoreSelection(bookmark);bookmark=null}
function insertSources(items:Array<{block:ComposerContextBlock;text?:string}>,replacementId?:string){if(sourceOwner!==props.chatId||!valid.value)return;if(bookmark&&!editor.value?.restoreSelection(bookmark)){emit('notify','插入位置已变化，请重新选择。');return}for(const item of items){if(replacementId)editor.value?.updateContext(replacementId,{block:item.block,text:item.text});else editor.value?.insertContext(item.block,item.text)}bookmark=null}
function changeSource(block:ComposerContextBlock){sourceDocumentId=draft.document.value.id;sourceOwner=props.chatId;bookmark=editor.value?.saveSelection()||null;showSource(block.source.kind,block)}
function openSource(block:ComposerContextBlock){if(block.source.kind==='file'&&block.source.path)emit('open-file',{chatId:block.source.chatId||props.chatId,path:block.source.path})}
async function copyReply(message:ChatMessage){try{await navigator.clipboard.writeText(message.content);copied.value=message.id;clearTimeout(copyTimer);copyTimer=setTimeout(()=>{copied.value=''},1800)}catch{emit('notify','复制失败，请重试。')}}
async function locateMessage(messageId:string){if(!chat.value)await session.reload();await nextTick();if(disposed||!visible())return;if(!chat.value?.messages.some(message=>message.id===messageId)){emit('notify','这条消息已不存在。');return}state.value.followBottom=false;await locate(messageId)}
async function locatePending(requestId?:string){await refreshSubchatIndex(props.parentChatId);await nextTick();if(disposed||!visible())return;const target=requestId?scroller.value?.querySelector<HTMLElement>(`[data-request-id="${CSS.escape(requestId)}"]`):scroller.value?.querySelector<HTMLElement>('[data-request-id]');if(target){state.value.followBottom=false;target.scrollIntoView({block:'center'});saveScroll()}}
function openFind(){if(visible())openWindowFind('workspace')}
function detailKey(event:KeyboardEvent){if(event.isComposing||event.keyCode===229||!visible())return;if((event.ctrlKey||event.metaKey)&&!event.shiftKey&&!event.altKey&&event.key.toLowerCase()==='f'){event.preventDefault();event.stopPropagation();openFind()}else if(event.key==='F3'){event.preventDefault();event.stopPropagation();if(!find.value?.opened)find.value?.open();else find.value?.step(event.shiftKey?-1:1)}}
onMounted(()=>{void loadConfig();void loadConversationResources(props.chatId);if(state.value.findState)find.value?.restore(state.value.findState)})
onBeforeUnmount(()=>{disposed=true;questionnaireGeneration++;offQuestionnaires?.();clearTimeout(copyTimer);clearTimeout(compositionTimer);saveScroll();state.value.findState=find.value?.snapshot();find.value?.close(false)})
defineExpose({openFind,stop,retry,locateMessage,locatePending,refresh:reload,get running(){return state.value.running},get stoppable(){return state.value.running||pendingCount.value>0},get selectedChatId(){return props.chatId}})
</script>
